def parseImpl(self, instring, loc, do_actions=True) -> ParseImplReturnType:
    if loc < len(instring):
        if instring[loc] == "\n":
            return loc + 1, "\n"
        else:
            raise ParseException(instring, loc, self.errmsg, self)
    elif loc == len(instring):
        return loc + 1, []
    else:
        raise ParseException(instring, loc, self.errmsg, self)
